using sv_51d194db94ac4e35b15cff0b27af5040.Models;

namespace sv_51d194db94ac4e35b15cff0b27af5040.Services;

public interface ITaskService
{
    Task<List<TaskItem>> GetAllTasksAsync();
    Task<TaskItem> CreateTaskAsync(string title, string assignee, string priority, DateTime dueDate);
    Task UpdateTaskStatusAsync(int taskId, string newStatus);
}

@using sv_51d194db94ac4e35b15cff0b27af5040.Models

<div class="task-card card mb-2">
    <div class="card-body p-2">
        <h6 class="card-title mb-1">@Task.Title</h6>
        <p class="text-muted mb-1 small">@Task.Assignee</p>
        <div class="d-flex justify-content-between align-items-center mb-1">
            <span class="badge @PriorityClass">@Task.Priority</span>
            <small class="text-muted">@Task.DueDate.ToString("MMM dd")</small>
        </div>
        <div class="d-flex gap-1">
            @if (CanMoveLeft)
            {
                <button class="btn btn-sm btn-outline-secondary" @onclick="HandleMoveLeft">← Move Left</button>
            }
            @if (CanMoveRight)
            {
                <button class="btn btn-sm btn-outline-secondary" @onclick="HandleMoveRight">Move Right →</button>
            }
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }

    private string PriorityClass => Task.Priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task HandleMoveLeft() => await OnMoveLeft.InvokeAsync(Task.Id);
    private async Task HandleMoveRight() => await OnMoveRight.InvokeAsync(Task.Id);
}

@using sv_51d194db94ac4e35b15cff0b27af5040.Models

<div class="kanban-column card">
    <div class="card-header d-flex justify-content-between align-items-center">
        <h5 class="mb-0">@ColumnName</h5>
        <span class="badge bg-secondary">@Tasks.Count</span>
    </div>
    <div class="card-body kanban-column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="ColumnIndex > 0"
                      CanMoveRight="ColumnIndex < 2"
                      OnMoveLeft="OnMoveLeft"
                      OnMoveRight="OnMoveRight" />
        }

        @if (showAddForm)
        {
            <AddTaskForm Status="@ColumnName"
                         OnTaskCreated="HandleTaskCreated"
                         OnCancel="() => showAddForm = false" />
        }
        else
        {
            <button class="btn btn-sm btn-outline-primary w-100 mt-2" @onclick="() => showAddForm = true">+ Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = default!;
    [Parameter, EditorRequired] public int ColumnIndex { get; set; }
    [Parameter] public List<TaskItem> Tasks { get; set; } = [];
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }
    [Parameter] public EventCallback<AddTaskForm.NewTaskRequest> OnAddTask { get; set; }

    private bool showAddForm;

    private async Task HandleTaskCreated(AddTaskForm.NewTaskRequest request)
    {
        await OnAddTask.InvokeAsync(request);
        showAddForm = false;
    }
}

