arguments.file_text:
@page "/board"
@rendermode InteractiveServer
@using sv_51d194db94ac4e35b15cff0b27af5040.Models
@using sv_51d194db94ac4e35b15cff0b27af5040.Services
@using sv_51d194db94ac4e35b15cff0b27af5040.Components.Board
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (isLoading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-sm btn-outline-danger ms-2" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats Total="allTasks.Count"
                TodoCount="TodoTasks.Count"
                InProgressCount="InProgressTasks.Count"
                DoneCount="DoneTasks.Count"
                OverdueCount="allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="searchText" @bind:event="oninput" />
    </div>

    <div class="row g-3">
        @{ var columns = new[] { ("To Do", 0, TodoTasks), ("In Progress", 1, InProgressTasks), ("Done", 2, DoneTasks) }; }
        @foreach (var (name, index, tasks) in columns)
        {
            <div class="col-md-4">
                <KanbanColumn ColumnName="@name"
                              ColumnIndex="index"
                              Tasks="tasks"
                              OnMoveLeft="HandleMoveLeft"
                              OnMoveRight="HandleMoveRight"
                              OnAddTask="(req) => HandleAddTask(name, req)" />
            </div>
        }
    </div>
}

@code {
    private List<TaskItem> allTasks = [];
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Statuses = ["To Do", "In Progress", "Done"];

    private List<TaskItem> FilteredTasks => string.IsNullOrWhiteSpace(searchText)
        ? allTasks
        : allTasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();

    private List<TaskItem> TodoTasks => FilteredTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> InProgressTasks => FilteredTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> DoneTasks => FilteredTasks.Where(t => t.Status == "Done").ToList();

    protected override async Task OnInitializedAsync() => await LoadTasks();

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleMoveLeft(int taskId)
    {
        var task = allTasks.FirstOrDefault(t => t.Id == taskId);
        if (task is null) return;

        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex <= 0) return;

        var newStatus = Statuses[currentIndex - 1];
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var idx = allTasks.FindIndex(t => t.Id == taskId);
            allTasks[idx] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private async Task HandleMoveRight(int taskId)
    {
        var task = allTasks.FirstOrDefault(t => t.Id == taskId);
        if (task is null) return;

        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex >= Statuses.Length - 1) return;

        var newStatus = Statuses[currentIndex + 1];
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var idx = allTasks.FindIndex(t => t.Id == taskId);
            allTasks[idx] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private async Task HandleAddTask(string status, AddTaskForm.NewTaskRequest request)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(request.Title, request.Assignee, request.Priority, request.DueDate);
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }
}

::deep .kanban-column {
    min-height: 400px;
}

::deep .kanban-column-body {
    min-height: 350px;
}

::deep .task-card {
    transition: box-shadow 0.15s;
}

::deep .task-card:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
}

